    colors = {v for row in grid for v in row if v != 0}
    source = next(c for c in colors if c != 1) if 1 not in colors else 1
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == source]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = [[grid[r][c] == source for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    # Palette is a repeated stripe in the lower portion; read its distinct colors in order.
    palette_cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, source)]
