    start_r = r0 - idx * sh
    for i, color in enumerate(palette):
        for dr in range(sh):
            for dc in range(sw):
                rr, cc = start_r + i * sh + dr, c0 + dc
                if 0 <= rr < h and shape[dr][dc]:
